export const courses={
am:{title:'Asset management',modules:[['What the job is','Asset managers make investment decisions for funds or clients under a stated objective, benchmark, risk limit and mandate. Analysts research securities; portfolio managers set exposures and monitor results.','Compare an active stock fund with an index fund: what does each promise to do?'],['Research and portfolio construction','Start with the mandate, then study businesses, valuation, portfolio concentration, liquidity and downside. A good thesis states the evidence, uncertainty and what would change your mind. Past performance does not establish future results.','Write a one paragraph thesis and name two risks.'],['Measure results responsibly','Separate market return from the effect of manager decisions. Compare with an appropriate benchmark over matching periods, and consider fees, risk and survivorship bias. A benchmark is a comparison tool, not a guarantee.','Explain why beating a broad index over one quarter may tell little about skill.']],interview:['Walk through an investment thesis and what would falsify it.','How can a portfolio manager measure whether active decisions added value?','Practice: present one company, its valuation drivers, two risks and one disconfirming fact.'],employers:[['Asset managers',['BlackRock','https://careers.blackrock.com/'],['Vanguard','https://www.vanguardjobs.com/'],['Fidelity Investments','https://jobs.fidelity.com/']]]},
ib:{title:'Investment banking',modules:[['How a deal team works','Investment bankers advise organizations on transactions such as mergers, acquisitions and capital raising. Analysts build materials, check data, model scenarios and coordinate diligence under tight deadlines.','List the questions you would ask before comparing two companies in an acquisition.'],['Valuation foundations','Comparable-company analysis, precedent transactions and discounted cash flow are frameworks, each sensitive to assumptions. Enterprise value and equity value differ because debt, cash and other claims matter.','Name two assumptions that could change a discounted cash flow valuation.'],['Deal process and judgment','A transaction moves through preparation, marketing or negotiation, diligence, documentation and closing; paths vary. Confidentiality, accuracy and clear escalation of errors are core professional skills.','Draft a concise update that flags a material discrepancy without overstating certainty.']],interview:['Walk me through the three financial statements and how they connect.','How would you value a company with negative earnings?','Practice: explain enterprise value versus equity value, then identify one limitation of comparable-company analysis.'],employers:[['Investment banks',['Goldman Sachs','https://www.goldmansachs.com/careers'],['JPMorgan Chase','https://careers.jpmorgan.com/'],['Morgan Stanley','https://www.morganstanley.com/people-opportunities/']]]},
wm:{title:'Wealth management',modules:[['The client relationship','Wealth managers help clients connect goals, cash flow, investing, taxes and life events. The job combines listening, analysis, planning and ongoing communication; duties and registrations vary.','Turn “I want to retire comfortably” into three clarifying questions.'],['Portfolio and suitability','A plan considers time horizon, liquidity needs, risk capacity and risk willingness. Diversification spreads exposures but cannot prevent loss. Product costs and conflicts should be understood.','Describe why an emergency fund and a long-term portfolio serve different goals.'],['Trust and professional conduct','Protect private information, document assumptions and explain tradeoffs in plain language. Verify a professional’s registration and disciplinary history through official tools.','Practice explaining market uncertainty to a nervous client without promising recovery.']],interview:['How do you explain a market decline to a client?','What would you do if a client goal conflicts with the proposed risk level?','Practice: summarize a fictional client goal, constraints, questions to resolve and next steps.'],employers:[['Wealth firms',['Charles Schwab','https://www.schwabjobs.com/'],['Fidelity Investments','https://jobs.fidelity.com/'],['Morgan Stanley','https://www.morganstanley.com/people-opportunities/']]]},
fp:{title:'Financial planning',modules:[['Build a plan from goals','Financial planners help organize goals, income, spending, savings, insurance, debt and investments. A useful plan makes assumptions visible and separates near-term priorities from long-term scenarios.','Create a short discovery checklist for a fictional new graduate.'],['Cash flow and retirement basics','A plan models contributions and possible future outcomes, not certainty. Tax treatment depends on account rules and personal circumstances; revisit assumptions when income or law changes.','Explain why a projection is not a promise.'],['Recommendations and follow-through','Explain options, costs, tradeoffs and missing information; document decisions and follow up. Credential and registration requirements depend on role and services.','Give a balanced explanation of paying down high-interest debt versus investing.']],interview:['How do you prioritize when a client has several competing goals?','What information would you gather before discussing retirement contributions?','Practice: explain one planning tradeoff in plain language without assuming a client’s answer.'],employers:[['Planning organizations',['CFP Board','https://www.cfp.net/why-cfp-certification/career-center'],['Fidelity Investments','https://jobs.fidelity.com/'],['Charles Schwab','https://www.schwabjobs.com/']]]},
cf:{title:'Corporate finance / FP&A',modules:[['The finance partner','FP&A teams help organizations plan revenue, costs, cash and investment. Analysts translate business activity into budgets, forecasts and decisions with department leaders.','Choose a campus club and name three drivers of its monthly budget.'],['Forecasting and variance','A forecast is an updated estimate, not a target or guarantee. Compare actual results with plan, identify the underlying drivers and distinguish timing from a lasting change.','A cost is 10% above plan: list questions before proposing a cut.'],['Communicate the decision','A concise analysis connects assumptions to outcomes, shows scenarios and calls out uncertainty. Spreadsheet accuracy, data checks and clear writing matter as much as formulas.','Write a three-line summary of a base case and downside case.']],interview:['How would you forecast revenue for a new product?','Tell me about a time data changed your conclusion.','Practice: explain a budget variance and the next analysis you would run.'],employers:[['Corporate finance teams',['Microsoft','https://careers.microsoft.com/'],['Amazon','https://www.amazon.jobs/'],['Target','https://corporate.target.com/careers']]]},
er:{title:'Equity research',modules:[['The research analyst role','Equity analysts study companies and industries, interpret filings and earnings, build forecasts and communicate risks. Research may support clients or internal investment teams; methods and regulatory obligations vary.','Find a company’s revenue segments in its annual report.'],['From business to valuation','Connect products, customers and competition to revenue, margins, cash flow and valuation. A price target is an assumption-based estimate, not a promise or an instruction to trade.','Name an operating metric that could matter more than headline revenue growth.'],['Evidence and uncertainty','Read primary filings, distinguish facts from estimates and compare management claims with cash flow and disclosures. Update a thesis when evidence changes and disclose uncertainty.','State one bull case, bear case and fact that would distinguish them.']],interview:['Pitch a company and defend your view with evidence.','How do you forecast revenue and operating margins?','Practice: summarize one risk factor from a company filing and explain how it could affect the model.'],employers:[['Research employers',['Morningstar','https://careers.morningstar.com/'],['Goldman Sachs','https://www.goldmansachs.com/careers'],['JPMorgan Chase','https://careers.jpmorgan.com/']]]},
risk:{title:'Risk management',modules:[['Risk is about uncertainty and exposure','Risk teams identify, measure and monitor exposures such as credit, market, liquidity, operations and model risk. They help leaders understand possible loss and control weaknesses; no model captures every scenario.','Sort a missed payment, a trading loss and a system outage into possible risk categories.'],['Measurement and limits','Metrics such as stress scenarios, concentration and expected loss answer different questions. Check data quality, assumptions, horizon and limitations before trusting a number.','Describe a severe-but-plausible scenario a simple average might miss.'],['Escalation and controls','Risk professionals document exceptions, communicate clearly and escalate according to policy. Independence and constructive challenge are valuable, even when bad news is inconvenient.','Write a brief escalation note separating observed facts from interpretation.']],interview:['How would you explain a model limitation to senior leaders?','What controls could reduce operational risk in a payment process?','Practice: describe a risk indicator, its blind spot and one follow-up control.'],employers:[['Risk teams',['JPMorgan Chase','https://careers.jpmorgan.com/'],['Bank of America','https://careers.bankofamerica.com/'],['Capital One','https://www.capitalonecareers.com/']]]},
quant:{title:'Quantitative finance',modules:[['Math, code and markets','Quantitative finance applies statistics, mathematics and programming to pricing, portfolio questions and risk. Roles vary from research to engineering; software quality and domain context are essential.','Explain why a model trained on past data might fail in a different market regime.'],['Test the model','A sound workflow checks data quality, assumptions, out-of-sample performance and transaction costs. Avoid look-ahead bias and overfitting; compare results with simple baselines.','Name two ways a backtest can look better than a real strategy.'],['Communicate limits','Translate technical results into decisions and clearly explain uncertainty, sensitivity and failure modes. A model is one input, not an oracle.','Give a one-minute explanation of a model’s main limitation to a nontechnical colleague.']],interview:['How would you detect overfitting in a backtest?','Describe a project where you validated data or code.','Practice: outline a test plan for a forecasting model, including a baseline and failure check.'],employers:[['Quant and data employers',['Jane Street','https://www.janestreet.com/join-jane-street/'],['Two Sigma','https://www.twosigma.com/careers/'],['Citadel','https://www.citadel.com/careers/']]]}
};
